import type { HTMLAttributes } from 'react';
import '../theme.css';
import './skeleton.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface SkeletonProps {
  width?: number | string;
  height?: number | string;
  radius?: 'xs' | 'sm' | 'round';
  className?: string;
}

/** A placeholder block. Hidden from assistive technology; wrap a group in SkeletonGroup. */
export function Skeleton({ width = '100%', height = 12, radius = 'xs', className }: SkeletonProps) {
  return (
    <span
      className={cx('ws-skeleton', className)}
      data-radius={radius === 'xs' ? undefined : radius}
      style={{ width, height }}
      aria-hidden="true"
    />
  );
}

export interface SkeletonGroupProps extends HTMLAttributes<HTMLDivElement> {
  /** The loading message for screen readers, for example "Loading saved styles". */
  label: string;
}

/**
 * Placeholder blocks plus one loading message. The message sits in its own
 * status region; aria-busy stays on the blocks, so it does not mute the message.
 */
export function SkeletonGroup({ label, className, children, ...rest }: SkeletonGroupProps) {
  return (
    <div className={cx('ws-skeleton-group', className)} {...rest}>
      <span className="ws-skeleton-group__label" role="status">
        {label}
      </span>
      <div className="ws-skeleton-group__blocks" aria-busy="true">
        {children}
      </div>
    </div>
  );
}

.ws-skeleton {
  box-sizing: border-box;
  display: block;
  max-width: 100%;
  border-radius: var(--ws-radius-xs);
  background: var(--ws-color-surface-hover);
  animation: ws-skeleton-pulse 1600ms var(--ws-ease) infinite;
}

.ws-skeleton[data-radius='sm'] {
  border-radius: var(--ws-radius-sm);
}

.ws-skeleton[data-radius='round'] {
  border-radius: 999px;
}

@keyframes ws-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ws-skeleton {
    animation: none;
  }
}

/* Set gap on the group; the blocks inherit it. The label is out of flow. */
.ws-skeleton-group {
  box-sizing: border-box;
  position: relative;
  display: grid;
  gap: var(--ws-space-2);
}

.ws-skeleton-group__blocks {
  display: grid;
  gap: inherit;
}

.ws-skeleton-group__label {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
